import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.7R1OEGYz.js";const k=JSON.parse('{"title":"Git integrations","description":"","frontmatter":{},"headers":[],"relativePath":"git.md","filePath":"git.md","lastUpdated":null}'),n={name:"git.md"};function o(l,s,p,r,h,c){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="git-integrations" tabindex="-1">Git integrations <a class="header-anchor" href="#git-integrations" aria-label="Permalink to &quot;Git integrations&quot;">​</a></h1><p>There are two ways to give a session access to your repositories. The manual one works out of the box; the OAuth one is nicer for more than one user.</p><h2 id="option-1-—-a-token-or-ssh-key" tabindex="-1">Option 1 — a token or SSH key <a class="header-anchor" href="#option-1-—-a-token-or-ssh-key" aria-label="Permalink to &quot;Option 1 — a token or SSH key&quot;">​</a></h2><p>Under <strong>Settings → Credentials</strong>, store an SSH private key, or a GitLab/GitHub token, plus optionally <code>known_hosts</code> for the server. Values are written to a per-user Kubernetes secret, never kept in the database, and never returned by the API.</p><p>Inside the session the token is wired up as a git credential helper for HTTPS remotes, and exported as <code>GITLAB_TOKEN</code> so <code>glab</code> works. A GitLab token needs <code>write_repository</code> for clone and push, or <code>api</code> if you want <code>glab</code> to open merge requests.</p><h2 id="option-2-—-connect-an-account-over-oauth" tabindex="-1">Option 2 — connect an account over OAuth <a class="header-anchor" href="#option-2-—-connect-an-account-over-oauth" aria-label="Permalink to &quot;Option 2 — connect an account over OAuth&quot;">​</a></h2><p>Users click <strong>Connect</strong> on the Account page and authorize once; sessions then clone and push without anyone handling a token. Tokens are stored in a per-user Kubernetes secret and refreshed automatically.</p><h3 id="your-callback-url" tabindex="-1">Your callback URL <a class="header-anchor" href="#your-callback-url" aria-label="Permalink to &quot;Your callback URL&quot;">​</a></h3><p>Register this as the redirect URI at the provider:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;your-host&gt;/api/git/callback/&lt;provider-id&gt;</span></span></code></pre></div><p>The last path segment is the <code>id</code> you give the provider in the values file — so with <code>id: gitlab</code> and host <code>hub.your-org.example</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://hub.your-org.example/api/git/callback/gitlab</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Not the same as your login callback</p><p>OIDC <strong>login</strong> uses <code>https://&lt;your-host&gt;/auth/callback</code>. That is a different thing from Git account connections. Registering one where the other belongs is the most common mistake here.</p></div><p>The URL is built from the configured frontend origin, not from the incoming request, so it stays correct behind a proxy.</p><h3 id="configure-the-provider" tabindex="-1">Configure the provider <a class="header-anchor" href="#configure-the-provider" aria-label="Permalink to &quot;Configure the provider&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Signs the OAuth &quot;state&quot; parameter. Random, 32+ characters, and stable across</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # restarts and replicas — a generated-per-start key breaks the flow on every restart.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  stateKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;random 32+ chars&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gitlab</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gitlab</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # github | gitlab</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      displayName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GitLab</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      baseUrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # e.g. https://gitlab.example.com for self-hosted</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      clientId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;application id&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      clientSecret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;secret&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      scopes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # empty = sensible defaults, see below</span></span></code></pre></div><p>Apply it with <code>helm upgrade -f</code>, and the <strong>Connect</strong> buttons appear on the Account page. The UI only shows that section when at least one provider has both a client id and a secret.</p><h3 id="at-the-provider" tabindex="-1">At the provider <a class="header-anchor" href="#at-the-provider" aria-label="Permalink to &quot;At the provider&quot;">​</a></h3><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-mZY9n" id="tab-TIDsDP8" checked><label data-title="GitLab" for="tab-TIDsDP8">GitLab</label><input type="radio" name="group-mZY9n" id="tab-FEU9I77"><label data-title="GitHub" for="tab-FEU9I77">GitHub</label></div><div class="blocks"><div class="language-text vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User Settings → Applications</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Redirect URI:  https://&lt;your-host&gt;/api/git/callback/gitlab</span></span>
<span class="line"><span>Confidential:  yes — the token exchange sends a client secret</span></span>
<span class="line"><span>Scopes:        api, read_user</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;api&quot; is needed to list your projects, &quot;read_user&quot; to identify you.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Settings → Developer settings → OAuth Apps</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Authorization callback URL:  https://&lt;your-host&gt;/api/git/callback/github</span></span>
<span class="line"><span>Scopes:                      repo, read:user</span></span></code></pre></div></div></div><p>Leaving <code>scopes</code> empty in the values file uses those defaults, so you normally do not set it at all.</p><h3 id="self-hosted-instances" tabindex="-1">Self-hosted instances <a class="header-anchor" href="#self-hosted-instances" aria-label="Permalink to &quot;Self-hosted instances&quot;">​</a></h3><p>Set <code>baseUrl</code> to the instance root, for example <code>https://gitlab.example.com</code>. The authorize, token, and API endpoints are derived from it.</p><h2 id="network-access" tabindex="-1">Network access <a class="header-anchor" href="#network-access" aria-label="Permalink to &quot;Network access&quot;">​</a></h2><p>No extra egress configuration is needed for gitlab.com, github.com, or a self-hosted instance on 443 or 22 — agent pods may already reach those ports. Only a Git server on a non-standard port needs an entry in <code>agent.extraEgressPorts</code>.</p>`,24)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
